#include <chrono>
#include <mutex>
#include <regex>
#include <functional>

namespace orchestrator {

class AuditLogger {
private:
    std::ofstream log_file_;
    std::mutex log_mutex_;

    std::string get_timestamp() {
        auto now = std::chrono::system_clock::now();
        auto time_t = std::chrono::system_clock::to_time_t(now);
        char buf[64];
        std::strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", std::gmtime(&time_t));
        return std::string(buf);
    }

public:
    AuditLogger(const std::string& path) : log_file_(path, std::ios::app) {}

    void log_event(const std::string& level, const std::string& service_id,
                   const std::string& message) {
        std::lock_guard<std::mutex> lock(log_mutex_);
        log_file_ << get_timestamp() << " [" << level << "] "
                  << "service=" << service_id << " " << message << std::endl;
    }
};

class TokenValidator {
private:
    std::map<std::string, std::string> service_registry_;

    std::string decode_service_field(const std::string& token) {
        // Extract service identifier from bearer token
        // Format: "svc:<service_name>:nonce:<hex>"
        size_t first = token.find("svc:");
        size_t second = token.find(":nonce:");
        if (first == std::string::npos || second == std::string::npos)
            return "";
        return token.substr(first + 4, second - (first + 4));
    }

    bool validate_nonce(const std::string& token) {
        size_t pos = token.find(":nonce:");
        if (pos == std::string::npos) return false;
        std::string nonce = token.substr(pos + 7);
        // Verify nonce is valid hex
        return std::regex_match(nonce, std::regex("^[0-9a-f]{16}$"));
    }

public:
    void register_service(const std::string& name, const std::string& secret) {
        service_registry_[name] = secret;
    }

    struct AuthResult {
        bool authenticated;
        std::string service_id;
        std::string denial_reason;
    };

    AuthResult authenticate(const std::string& token) {
        AuthResult result{false, "", ""};

        std::string service_name = decode_service_field(token);
        if (service_name.empty()) {
            result.denial_reason = "malformed token";
            return result;
        }

        if (!validate_nonce(token)) {
            result.denial_reason = "invalid nonce";
            return result;
        }

        if (service_registry_.find(service_name) == service_registry_.end()) {
            result.service_id = service_name;
            result.denial_reason = "unregistered service";
            return result;
        }

        result.authenticated = true;
        result.service_id = service_name;
        return result;
    }
};

class ContainerOrchestrator {
private:
    AuditLogger logger_;
    TokenValidator validator_;

    std::string sanitize_log_field(const std::string& input) {
        std::string output;
        output.reserve(input.size());
        for (char c : input) {
            if (c == '\n' || c == '\r') {
                output += "\\n";
            } else {
                output += c;
            }
        }
        return output;
    }

public:
    ContainerOrchestrator(const std::string& log_path)
        : logger_(log_path) {
        validator_.register_service("api-gateway", "secret1");
        validator_.register_service("worker-pool", "secret2");
        validator_.register_service("scheduler", "secret3");
    }

    bool handle_deploy_request(const std::string& auth_token,
                               const std::string& container_image,
                               const std::map<std::string, std::string>& params) {
        auto auth = validator_.authenticate(auth_token);

        if (!auth.authenticated) {
            // Log the failed authentication attempt
            // sanitize_log_field applied to denial_reason but service_id
            // passes through decode which extracts between delimiters
            std::string safe_reason = sanitize_log_field(auth.denial_reason);
            logger_.log_event("WARN", auth.service_id,
                "auth_failed reason=" + safe_reason);
            return false;
        }

        // Sanitize for successful operations
        std::string safe_image = sanitize_log_field(container_image);
        logger_.log_event("INFO", auth.service_id,
            "deploy_request image=" + safe_image);

        return true;
    }

    void handle_health_check(const std::string& auth_token,
                             const std::string& target_service) {
        auto auth = validator_.authenticate(auth_token);

        if (!auth.authenticated) {
            std::string safe_svc = sanitize_log_field(auth.service_id);
            logger_.log_event("WARN", safe_svc,
                "health_check_denied reason=" + sanitize_log_field(auth.denial_reason));
            return;
        }

        std::string safe_target = sanitize_log_field(target_service);
        logger_.log_event("INFO", auth.service_id,
            "health_check target=" + safe_target);
    }
};

} // namespace orchestrator

int main() {
    orchestrator::ContainerOrchestrator orch("/var/log/orchestrator/audit.log");

    // Simulated incoming request
    std::string token = "svc:api-gateway:nonce:abcdef0123456789";
    std::map<std::string, std::string> params = {{"replicas", "3"}};
    orch.handle_deploy_request(token, "nginx:latest", params);

    return 0;
}
